prog.write_text('''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            components.append(cells)
    out = [row[:] for row in grid]
    if components:
        for r, c in max(components, key=len):
            out[r][c] = 8
        for r, c in min(components, key=len):
            out[r][c] = 7
    return out
''')
